.chat-note.is-uncertain{background:#fff7e0;border-color:#e6c36a;color:#6b4a00}
.dark .chat-turn.is-uncertain p,.dark .chat-note.is-uncertain{background:#3a2e12;border-color:#7a6226;color:#f1d28a}
.chat-evidence{display:block;margin-top:4px;overflow-wrap:anywhere}.chat-evidence a{color:#2766c7;text-decoration:underline}
